(function(){
var cv=document.getElementById('game'),c=cv.getContext('2d');
var st=document.getElementById('game-status'),startBtn=document.getElementById('start-game');
var timeEl=document.getElementById('time'),scoreEl=document.getElementById('score');
var W=300,H=400,LANES=3,LW=W/LANES;
var lane=1,px=1*LW+LW/2,cars=[],running=false,t=0,score=0,last=0,spawn=0,offset=0,raf=0,DUR=30;
function setStatus(s,txt){st.setAttribute('data-state',s);st.textContent=txt;}
function move(d){if(!running)return;lane=Math.max(0,Math.min(LANES-1,lane+d));}
function start(){
lane=1;px=LW*1.5;cars=[];t=0;score=0;spawn=0;offset=0;running=true;last=performance.now();
timeEl.textContent=DUR;scoreEl.textContent=0;
startBtn.textContent='Starta om';
setStatus('playing','Kör! Undvik bilarna!');
cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);
}
function end(win){
running=false;
setStatus(win?'won':'lost',win?'Du vann! Poäng: '+score+'. Tryck Starta om för att köra igen.':'Krock! Poäng: '+score+'. Tryck Starta om för att försöka igen.');
startBtn.textContent='Spela igen';
}
function loop(now){
if(!running){draw();return;}
var dt=Math.min(0.05,(now-last)/1000);last=now;
t+=dt;
var speed=130+t*4;
offset=(offset+speed*dt)%40;
px+=((lane*LW+LW/2)-px)*Math.min(1,dt*12);
spawn-=dt;
if(spawn<=0){cars.push({l:Math.floor(Math.random()*LANES),y:-60,col:['#e74c3c','#3498db','#9b59b6','#e67e22'][Math.floor(Math.random()*4)]});spawn=0.9-Math.min(0.4,t*0.012)+Math.random()*0.4;}
for(var i=cars.length-1;i>=0;i--){
var k=cars[i];k.y+=speed*dt*0.8;
if(k.y>H+60){cars.splice(i,1);score+=10;scoreEl.textContent=score;continue;}
var kx=k.l*LW+LW/2;
if(Math.abs(kx-px)<30&&Math.abs(k.y-(H-70))<56){draw();end(false);return;}
}
timeEl.textContent=Math.max(0,Math.ceil(DUR-t));
if(t>=DUR){draw();end(true);return;}
draw();raf=requestAnimationFrame(loop);
}
function car(x,y,col){
c.fillStyle=col;c.fillRect(x-18,y-30,36,60);
c.fillStyle='#bfe9ff';c.fillRect(x-13,y-18,26,14);
c.fillStyle='#111';c.fillRect(x-21,y-24,5,14);c.fillRect(x+16,y-24,5,14);c.fillRect(x-21,y+10,5,14);c.fillRect(x+16,y+10,5,14);
}
function draw(){
c.fillStyle='#444';c.fillRect(0,0,W,H);
c.fillStyle='#fff';
for(var l=1;l<LANES;l++){for(var y=-40;y<H;y+=40){c.fillRect(l*LW-2,y+offset,4,20);}}
cars.forEach(function(k){car(k.l*LW+LW/2,k.y,k.col);});
car(px,H-70,'#ffd23f');
}
document.addEventListener('keydown',function(e){
var k=e.key;
if(k==='ArrowLeft'||k==='a'||k==='A'){move(-1);e.preventDefault();}
else if(k==='ArrowRight'||k==='d'||k==='D'){move(1);e.preventDefault();}
});
document.getElementById('left-btn').addEventListener('click',function(){move(-1);});
document.getElementById('right-btn').addEventListener('click',function(){move(1);});
cv.addEventListener('pointerdown',function(e){var r=cv.getBoundingClientRect();move((e.clientX-r.left)<r.width/2?-1:1);});
startBtn.addEventListener('click',start);
draw();
})();
